CREATE TABLE campaigns(campaign_id text NOT NULL,version text NOT NULL,owner_id text NOT NULL,currency text NOT NULL,budget_minor bigint NOT NULL CHECK(budget_minor>0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,brand_policy_version text NOT NULL,evidence_boundary text NOT NULL,brief_fingerprint char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(campaign_id,version));
CREATE TABLE campaign_evidence(evidence_fingerprint char(64) PRIMARY KEY,evidence_id text NOT NULL,campaign_id text NOT NULL,campaign_version text NOT NULL,evidence_type text NOT NULL,status text NOT NULL,confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1),source_url text NOT NULL,observed_at timestamptz NOT NULL,synthetic boolean NOT NULL DEFAULT true,payload jsonb NOT NULL,UNIQUE(campaign_id,campaign_version,evidence_id));
CREATE TABLE work_graphs(graph_fingerprint char(64) PRIMARY KEY,campaign_id text NOT NULL,campaign_version text NOT NULL,auto_publish boolean NOT NULL CHECK(auto_publish=false),spend_authorized boolean NOT NULL CHECK(spend_authorized=false),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_budgets(budget_fingerprint char(64) PRIMARY KEY,campaign_id text NOT NULL,currency text NOT NULL,budget_minor bigint NOT NULL,planning_cap_minor bigint NOT NULL,reserve_minor bigint NOT NULL,spend_authorized boolean NOT NULL CHECK(spend_authorized=false),payload jsonb NOT NULL);
CREATE TABLE campaign_assets(asset_fingerprint char(64) PRIMARY KEY,asset_id text NOT NULL,campaign_id text NOT NULL,campaign_version text NOT NULL,channel text NOT NULL,locale text NOT NULL,status text NOT NULL,brand_policy_version text NOT NULL,auto_publish boolean NOT NULL CHECK(auto_publish=false),payload jsonb NOT NULL,UNIQUE(campaign_id,campaign_version,asset_id));
CREATE TABLE asset_reviews(review_fingerprint char(64) PRIMARY KEY,asset_fingerprint char(64) NOT NULL REFERENCES campaign_assets(asset_fingerprint),reviewer_id text NOT NULL,reviewer_role text NOT NULL,decision text NOT NULL,rationale text NOT NULL,publishing_authorized boolean NOT NULL CHECK(publishing_authorized=false),spend_authorized boolean NOT NULL CHECK(spend_authorized=false),reviewed_at timestamptz NOT NULL);
CREATE TABLE campaign_packets(packet_fingerprint char(64) PRIMARY KEY,campaign_id text NOT NULL,campaign_version text NOT NULL,status text NOT NULL,publishing_authorized boolean NOT NULL CHECK(publishing_authorized=false),spend_authorized boolean NOT NULL CHECK(spend_authorized=false),payload jsonb NOT NULL);
CREATE TABLE campaign_handoffs(handoff_fingerprint char(64) PRIMARY KEY,packet_fingerprint char(64) NOT NULL REFERENCES campaign_packets(packet_fingerprint),target_project text NOT NULL,status text NOT NULL,auto_publish boolean NOT NULL CHECK(auto_publish=false),causal_claim_allowed boolean NOT NULL CHECK(causal_claim_allowed=false),payload jsonb NOT NULL);
CREATE TABLE campaign_outcomes(outcome_fingerprint char(64) PRIMARY KEY,packet_fingerprint char(64) NOT NULL REFERENCES campaign_packets(packet_fingerprint),metric text NOT NULL,value numeric NOT NULL,causal_claim_allowed boolean NOT NULL CHECK(causal_claim_allowed=false),revenue_attribution_allowed boolean NOT NULL CHECK(revenue_attribution_allowed=false),observed_at timestamptz NOT NULL,payload jsonb NOT NULL);
CREATE TABLE campaign_audit(event_hash char(64) PRIMARY KEY,event_id text NOT NULL UNIQUE,campaign_id text NOT NULL,previous_hash text NOT NULL,actor_id text NOT NULL,actor_role text NOT NULL,event_type text NOT NULL,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL);
CREATE TABLE campaign_dlq(job_id text PRIMARY KEY,attempts integer NOT NULL,reason text NOT NULL,auto_replay boolean NOT NULL CHECK(auto_replay=false),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX campaign_assets_lookup_idx ON campaign_assets(campaign_id,campaign_version,channel);
CREATE INDEX campaign_audit_lookup_idx ON campaign_audit(campaign_id,occurred_at,event_id);
